/// <summary>
/// PaffH 03.02.22
/// </summary>
/// <param name = "_element">FormRun</param>
/// <returns>NDXProdIdentControlPanelForm</returns>
public static NDXProdIdentControlPanelForm NewFromForm(FormRun _element)
{
    NDXProdIdentControlPanelForm form;
    form = new NDXProdIdentControlPanelForm();
    form.InitFromFormRun(_element);
    return form;
}

/// <summary>
/// PaffH 03.02.22
/// </summary>
/// <param name = "_formRun">FormRun</param>
protected void InitFromFormRun(FormRun _formRun)
{
    thisFormRun = _formRun;
    QueueInfoPAStatusChanged_ds = thisFormRun.dataHelper().FindDataSource(formDataSourceStr(NDXProdIdentControlPanel, QueueInfoPAStatusChanged));
    QueueInfoResponseLabelSaved_ds = thisFormRun.dataHelper().FindDataSource(formDataSourceStr(NDXProdIdentControlPanel, QueueInfoResponseLabelSaved));
    NDXProdIdentControlPanelParameters_ds = thisFormRun.dataHelper().FindDataSource(formDataSourceStr(NDXProdIdentControlPanel, NDXProdIdentControlPanelParameters));
    NDXPAWithLabelInfo_ds = thisFormRun.dataHelper().FindDataSource(formDataSourceStr(NDXProdIdentControlPanel, NDXPAWithLabelInfo));
    BatchJobHistory_NDXProdIdentControlPanelParameters_LabelSaved_ds = thisFormRun.dataHelper().FindDataSource(formDataSourceStr(NDXProdIdentControlPanel, BatchJobHistory_NDXProdIdentControlPanelParameters_LabelSaved));
    BatchJobHistory_NDXProdIdentControlPanelParameters_LabelMaintained_ds = thisFormRun.dataHelper().FindDataSource(formDataSourceStr(NDXProdIdentControlPanel, BatchJobHistory_NDXProdIdentControlPanelParameters_LabelMaintained));
    NDXProdIdentOZMapping_ds = thisFormRun.dataHelper().FindDataSource(formDataSourceStr(NDXProdIdentControlPanel, NDXProdIdentOZMapping_10));
}

/// <summary>
/// PaffH 11.05.22
/// </summary>
/// <returns>NDXPAWithLabelInfo</returns>
public NDXPAWithLabelInfo parmNDXPAWithLabelInfo()
{
    NDXPAWithLabelInfo_ds.reread();
    return NDXPAWithLabelInfo_ds.cursor();
}

/// <summary>
/// PaffH 03.02.22
/// show batchJob details (BatchJobEnhanced)
/// </summary>
/// <param name = "_batchHeaderRecId">RefRecId</param>
public void showBatchJob(RefRecId _batchHeaderRecId)
{
    Args args;
    BatchJob batchJob;
    select firstonly batchJob where batchJob.RecId == _batchHeaderRecId;
    args = new Args();
    args.name(formStr(BatchJobEnhanced));
    args.record(batchJob);
    MenuFunction menuFunction = new MenuFunction(menuItemDisplayStr(BatchJobEnhanced), MenuItemType::Display);
    menuFunction.run(args);
}

/// <summary>
/// PaffH 19.05.22
/// see: form.BatchJobHistory.showLog()
/// </summary>
/// <param name = "labelSaved">boolean</param>
public void showLog(boolean labelSaved = true)
{
    InfologData data;
    BatchJobHistory batchJobHistory = labelSaved ? this.parmBatchJobHistory_NDXProdIdentControlPanelParameters_LabelSaved() : this.parmBatchJobHistory_NDXProdIdentControlPanelParameters_LabelMaintained();

    if (batchJobHistory && batchJobHistory.RecId)
    {
        //BatchHistory batchHistoryRecord = this.findFirstBatchHistoryTask(batchJobHistory.RecId);

        //using (SysErrorMessageHelpScope scope = this.newErrorContextShowBatchLog(batchHistoryRecord.ClassNumber, batchHistoryRecord.Caption, batchHistoryRecord.Parameters))
        {
            setprefix(strfmt("@SYS113156", batchJobHistory.Caption, int642str(batchJobHistory.RecId)));
            data = BatchJobHistory::showLog(batchJobHistory.RecId);
            int countItems = conlen(data);

            boolean addedLog = false;
            for(int i = 1; i <= countItems; i += 3)
            {
                if (conLen(conPeek(data, i+2)) == 0)
                {
                    continue;
                }

                addedLog = true;

                setprefix(strfmt("@SYS107863", conpeek(data, i), int642str(conpeek(data, i+1))));
                infolog.import(conpeek(data, i+2));
            }

            if (addedLog)
            {
                infolog.import([[1], [0, "@ApplicationFoundation:BatchTaskLogEndMarker"]]);
            }
            else
            {
                Message::Add(MessageSeverity::Informational, "@ApplicationFoundation:BatchTaskLogEmpty");
            }
        }
    }
}

/// <summary>
/// PaffH 19.05.22
/// </summary>
/// <param name = "_batchJobHistoryId">recId</param>
/// <returns>BatchHistory</returns>
public BatchHistory findFirstBatchHistoryTask(recId _batchJobHistoryId)
{
    BatchHistory batchHistory;
    BatchJobHistory batchJobHistory;

    select firstonly batchHistory
        where batchHistory.BatchJobHistoryId == _batchJobHistoryId
        exists join batchJobHistory where batchJobHistory.RecId == _batchJobHistoryId &&
            (batchJobHistory.BatchCreatedBy == curuserid() || Batch::isBatchOperator());

    return batchHistory;
}

/// <summary>
/// PaffH 24.10.23
/// </summary>
public void checkOZMappingProdIdentControlPanel()
{
    NDXProdIdentOZMapping nDXProdIdentOZMapping = NDXProdIdentOZMapping_ds.cursor() as NDXProdIdentOZMapping;
    if (Box::yesNo(strFmt("@NDX:NDXCheckOnlyOneItem", nDXProdIdentOZMapping.ItemIdOZ), DialogButton::No) == DialogButton::Yes)
    {
        NDXProdIdentOZMapping::checkOZMappingProdIdentControlPanel(true, nDXProdIdentOZMapping.ItemIdOZ);
    }
    else
    {
        NDXProdIdentOZMapping::checkOZMappingProdIdentControlPanel(true);
    }
}
